const CANVAS_W = 700;
const CANVAS_H = 500;

/**
 * Rotate a {dx, dy} offset by deg degrees (0, 90, 180, 270).
 */
function rotateOffset(dx, dy, deg) {
  switch ((deg % 360 + 360) % 360) {
    case 0:
      return {
        dx,
        dy
      };
    case 90:
      return {
        dx: -dy,
        dy: dx
      };
    case 180:
      return {
        dx: -dx,
        dy: -dy
      };
    case 270:
      return {
        dx: dy,
        dy: -dx
      };
    default:
      return {
        dx,
        dy
      };
  }
}

