// Module
___CSS_LOADER_EXPORT___.push([module.id, ".bw-circuit-designer {\n    color: #334155;\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n.bw-circuit-designer,\n.bw-circuit-designer * {\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] input,\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] select,\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] textarea {\n    font-family: inherit !important;\n    color: #334155 !important;\n    background: #ffffff !important;\n    border-color: #cbd5e1 !important;\n}\n\n/* Buttons own their active/inactive colors inline. A broad `button` rule here\n * used !important and silently painted every selected toggle white, making\n * Build/Sim, power, view and panel navigation indistinguishable. */\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] button {\n    font-family: inherit !important;\n}\n\n/* The toolbar is a single control row. Keep every button and group on the\n * same border-box baseline; otherwise upstream button defaults make the\n * panel-nav cells visibly drift from Build/Power/Undo on Safari. */\n\n.bw-circuit-designer [data-circuit-toolbar] button {\n    box-sizing: border-box !important;\n    height: 34px !important;\n    min-height: 34px !important;\n}\n\n.bw-circuit-designer [data-circuit-toolbar] > [data-circuit-control-group] {\n    box-sizing: border-box !important;\n    height: 34px !important;\n    min-height: 34px !important;\n    align-self: center !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] button[data-circuit-toggle-state=\"selected\"] {\n    background: #2563eb !important;\n    color: #ffffff !important;\n    border-color: #1d4ed8 !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] button[data-circuit-toggle-state=\"unselected\"] {\n    background: #475569 !important;\n    color: #ffffff !important;\n    border-color: #64748b !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] {\n    background: #f8fafc !important;\n}\n\n/* SchematicPanel uses SVG presentation attributes so it also works outside\n * the themed designer. In the light designer those defaults must be replaced\n * together; otherwise labels and wires stay pale on a pale canvas. */\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] text {\n    fill: #334155 !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] path,\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] rect,\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] line {\n    stroke: #64748b !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] svg[data-schematic] circle {\n    fill: #475569 !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"light\"] [style*=\"monospace\"] {\n    font-family: inherit !important;\n}\n\n.bw-circuit-designer[data-bw-circuit-theme=\"dark\"] {\n    color: #dbeafe;\n    background: #111827;\n}\n", ""]);
